using System;using System.Linq;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Media;using System.Windows.Automation;using Gunt.ControlCenter.Models;using Gunt.ControlCenter.Services;
namespace Gunt.ControlCenter.Views {
 public sealed partial class LaunchpadWindow {
  int Confirm(string title,string text,params string[] choices){bool previous=modal;modal=true;try{return UxTheme.Confirm(this,title,text,choices);}finally{modal=previous;}}
  void ShowModal(Window dialog){bool previous=modal;modal=true;try{dialog.ShowDialog();}finally{modal=previous;Activate();search.Focus();}}
  ContextMenu AppMenu(ApplicationEntry app){var menu=new ContextMenu();menu.Opened+=delegate{menuOpen=true;};menu.Closed+=delegate{menuOpen=false;};Action<ItemsControl,string,Action> add=(owner,title,action)=>{var option=new MenuItem{Header=title};option.Click+=delegate{Safe(action);};owner.Items.Add(option);};
   if(app.Kind=="group"){add(menu,"폴더 이름 바꾸기",()=>NameEditor("폴더 이름",app.Name,name=>Mutate(c=>c.Folders.First(x=>x.Id==app.Id).Name=name)));add(menu,"폴더 해제",()=>{Mutate(c=>DesktopService.DeleteLaunchpadFolder(c,app.Id));RefreshGrid();});return menu;}
   var item=DesktopService.Item(config,app.Id);add(menu,item.Favorite?"즐겨찾기 해제":"즐겨찾기에 추가",()=>{Mutate(c=>DesktopService.Item(c,app.Id).Favorite=!item.Favorite);RefreshGrid();});
   var move=new MenuItem{Header="카테고리로 이동"};menu.Items.Add(move);foreach(var categoryTarget in config.Categories.Where(x=>x.Id!="all"&&x.Id!="favorites")){var target=categoryTarget;add(move,target.Name,()=>MoveApp(app.Id,target.Id,null));}
   var into=new MenuItem{Header="폴더로 이동"};menu.Items.Add(into);foreach(var folderTarget in config.Folders){var target=folderTarget;add(into,target.Name,()=>MoveApp(app.Id,target.Category,target.Id));}into.IsEnabled=into.Items.Count>0;
   if(item.Folder!=null)add(menu,"폴더에서 꺼내기",()=>MoveApp(app.Id,item.Category??app.Category,null));
   add(menu,"앞으로 이동",()=>{int index=Array.FindIndex(visible,x=>x.Id==app.Id);if(index>0)Reorder(app.Id,visible[index-1].Id);});
   add(menu,"뒤로 이동",()=>{int index=Array.FindIndex(visible,x=>x.Id==app.Id);if(index>=0&&index<visible.Length-1)Reorder(visible[index+1].Id,app.Id);});
   add(menu,"표시 이름 · 별칭 · 아이콘",()=>EditItem(app));
   if(app.Source=="사용자")add(menu,"바로가기 편집",()=>EditShortcut(app));
   add(menu,"Launchpad에서 제거",()=>{if(Confirm("바로가기 제거",app.Name+" 항목만 제거합니다. 설치된 앱과 파일은 보존합니다.","제거","취소")!=0)return;Mutate(c=>{if(app.Source=="사용자"){c.Shortcuts.RemoveAll(x=>x.Id==app.Id);c.Items.Remove(app.Id);}else DesktopService.Item(c,app.Id).Hidden=true;});RefreshGrid();});return menu;
  }
  Window Form(string title,out StackPanel fields,out TextBlock error,out WrapPanel actions){var window=UxTheme.Dialog(this,title,560,600);var layout=new DockPanel{Margin=new Thickness(16)};var footer=new StackPanel();DockPanel.SetDock(footer,Dock.Bottom);layout.Children.Add(footer);error=new TextBlock{Foreground=UxTheme.Accent,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,8,0,8)};footer.Children.Add(error);actions=new WrapPanel{HorizontalAlignment=HorizontalAlignment.Right};footer.Children.Add(actions);fields=new StackPanel();layout.Children.Add(new ScrollViewer{Content=fields,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled});window.Content=layout;return window;}
  static void Field(Panel panel,string label,UIElement input){panel.Children.Add(new TextBlock{Text=label,Foreground=UxTheme.Muted,Margin=new Thickness(0,8,0,4)});panel.Children.Add(input);if(input is DependencyObject)AutomationProperties.SetName((DependencyObject)input,label);}
  void FinishForm(Window window,WrapPanel actions,TextBlock error,Func<string> fingerprint,Action save){string initial=fingerprint();bool saved=false;var cancel=new Button{Content="취소"};cancel.Click+=delegate{window.Close();};var accept=new Button{Content="저장",IsDefault=true,BorderBrush=UxTheme.Accent};accept.Click+=delegate{try{save();saved=true;window.Close();}catch(Exception e){error.Text=e.Message;}};actions.Children.Add(accept);actions.Children.Add(cancel);window.Closing+=delegate(object sender,System.ComponentModel.CancelEventArgs e){if(!saved&&fingerprint()!=initial&&UxTheme.Confirm(window,"미저장 변경","편집한 내용을 버릴까요?","버리기","계속 편집")!=0)e.Cancel=true;};}
  void NameEditor(string title,string value,Action<string> save){StackPanel fields;TextBlock error;WrapPanel actions;var window=Form(title,out fields,out error,out actions);window.Height=250;var name=new TextBox{Text=value??"",MaxLength=40};Field(fields,"이름",name);FinishForm(window,actions,error,()=>name.Text,()=>{if(String.IsNullOrWhiteSpace(name.Text))throw new ArgumentException("이름을 입력하세요.");save(name.Text.Trim());BuildCategories();RefreshGrid();});ShowModal(window);}
  void EditItem(ApplicationEntry app){StackPanel fields;TextBlock error;WrapPanel actions;var window=Form("항목 표시",out fields,out error,out actions);var item=DesktopService.Item(config,app.Id);var label=new TextBox{Text=item.Label??app.Name,MaxLength=100};var aliases=new TextBox{Text=item.Aliases??"",MaxLength=300};var pose=new ComboBox{ItemsSource=LaunchpadIcons.Poses,SelectedItem=item.Pose??"default"};Field(fields,"표시 이름",label);Field(fields,"검색 별칭",aliases);Field(fields,"마스코트 포즈 (테마를 사용할 때)",pose);fields.Children.Add(new TextBlock{Text="없는 포즈는 원래 앱 아이콘으로 표시합니다.",Foreground=UxTheme.Muted,Margin=new Thickness(0,8,0,0)});FinishForm(window,actions,error,()=>label.Text+"\n"+aliases.Text+"\n"+pose.SelectedItem,()=>{if(String.IsNullOrWhiteSpace(label.Text))throw new ArgumentException("표시 이름을 입력하세요.");Mutate(c=>{var updated=DesktopService.Item(c,app.Id);updated.Label=label.Text.Trim();updated.Aliases=aliases.Text;updated.Pose=Convert.ToString(pose.SelectedItem);});RefreshGrid();});ShowModal(window);}
  void EditShortcut(ApplicationEntry app){StackPanel fields;TextBlock error;WrapPanel actions;var window=Form(app==null?"바로가기 추가":"바로가기 편집",out fields,out error,out actions);var name=new TextBox{Text=app==null?"":app.Name,MaxLength=100};var kind=new ComboBox{ItemsSource=new[]{"exe","shortcut","folder","website"},SelectedItem=app==null?"exe":app.Kind};var target=new TextBox{Text=app==null?"":app.Target};var arguments=new TextBox{Text=app==null?"[]":service.Json.Serialize(app.Arguments),AcceptsReturn=true,Height=70,TextWrapping=TextWrapping.Wrap};Field(fields,"이름",name);Field(fields,"종류 (exe / shortcut / folder / website)",kind);Field(fields,"실행 대상 (절대 경로 또는 HTTP/HTTPS)",target);Field(fields,"인수 — JSON 문자열 배열, 실행 파일만",arguments);FinishForm(window,actions,error,()=>name.Text+kind.SelectedItem+target.Text+arguments.Text,()=>{var entry=new ApplicationEntry{Id=app==null?"custom-"+Guid.NewGuid().ToString("N"):app.Id,Name=name.Text.Trim(),Kind=Convert.ToString(kind.SelectedItem),Target=target.Text.Trim(),Arguments=service.Json.Deserialize<string[]>(arguments.Text),Source="사용자",Category=category=="all"||category=="favorites"?"utilities":category,Context="사용자 바로가기"};DesktopService.ValidateApplication(entry,true);Mutate(c=>{c.Shortcuts.RemoveAll(x=>x.Id==entry.Id);c.Shortcuts.Add(entry);});LoadCatalog(false);});ShowModal(window);}
  void EditCategory(LaunchpadCategory categoryItem){StackPanel fields;TextBlock error;WrapPanel actions;var dialog=Form("카테고리 설정",out fields,out error,out actions);dialog.Height=340;var name=new TextBox{Text=categoryItem.Name,MaxLength=40};var pose=new ComboBox{ItemsSource=LaunchpadIcons.Poses,SelectedItem=categoryItem.Pose??"default"};Field(fields,"이름",name);Field(fields,"카테고리 마스코트",pose);FinishForm(dialog,actions,error,()=>name.Text+pose.SelectedItem,()=>{if(String.IsNullOrWhiteSpace(name.Text))throw new ArgumentException("이름을 입력하세요.");Mutate(c=>{var item=c.Categories.First(x=>x.Id==categoryItem.Id);item.Name=name.Text.Trim();item.Pose=Convert.ToString(pose.SelectedItem);});BuildCategories();RefreshGrid();});ShowModal(dialog);}
  void EditCategories(){StackPanel fields;TextBlock error;WrapPanel actions;var window=Form("카테고리 · 폴더 관리",out fields,out error,out actions);var list=new ListBox{Height=240,ItemsSource=config.Categories};fields.Children.Add(list);var bar=new WrapPanel{Margin=new Thickness(0,12,0,0)};fields.Children.Add(bar);
   Action refresh=()=>{BuildCategories();RefreshGrid();list.ItemsSource=config.Categories;};
   bar.Children.Add(MakeButton("카테고리 추가",()=>{NameEditor("카테고리 추가","",name=>Mutate(c=>c.Categories.Add(new LaunchpadCategory{Id="category-"+Guid.NewGuid().ToString("N"),Name=name})));refresh();}));
   bar.Children.Add(MakeButton("이름",()=>{var selectedCategory=list.SelectedItem as LaunchpadCategory;if(selectedCategory==null)return;EditCategory(selectedCategory);refresh();}));
   bar.Children.Add(MakeButton("삭제",()=>{var selectedCategory=list.SelectedItem as LaunchpadCategory;if(selectedCategory==null)return;if(selectedCategory.Builtin)throw new ArgumentException("기본 카테고리는 삭제할 수 없습니다.");Mutate(c=>DesktopService.DeleteLaunchpadCategory(c,selectedCategory.Id));refresh();}));
   foreach(int delta in new[]{-1,1}){int direction=delta;bar.Children.Add(MakeButton(delta<0?"위로":"아래로",()=>{var selectedCategory=list.SelectedItem as LaunchpadCategory;if(selectedCategory==null)return;Mutate(c=>{var item=c.Categories.First(x=>x.Id==selectedCategory.Id);int index=c.Categories.IndexOf(item),to=Math.Max(0,Math.Min(c.Categories.Count-1,index+direction));c.Categories.RemoveAt(index);c.Categories.Insert(to,item);});refresh();list.SelectedItem=config.Categories.First(x=>x.Id==selectedCategory.Id);}));}
   fields.Children.Add(MakeButton("선택 카테고리에 폴더 만들기",()=>{var selectedCategory=list.SelectedItem as LaunchpadCategory;if(selectedCategory==null||selectedCategory.Id=="all"||selectedCategory.Id=="favorites")throw new ArgumentException("폴더를 넣을 카테고리를 선택하세요.");NameEditor("앱 폴더 만들기","",name=>Mutate(c=>c.Folders.Add(new LaunchpadFolder{Id="group-"+Guid.NewGuid().ToString("N"),Name=name,Category=selectedCategory.Id})));refresh();}));
   var close=new Button{Content="닫기",IsCancel=true};actions.Children.Add(close);ShowModal(window);
  }
  void EditPreferences(){modal=true;try{LaunchpadPreferences.Show(this,service);}finally{modal=false;config=service.Launchpad();BuildCategories();RefreshGrid();Activate();search.Focus();}}
  void PreviewSession(ApplicationEntry app){modal=true;try{var preset=service.Sessions().Presets.FirstOrDefault(x=>x.Id==app.Target);if(preset==null)throw new ArgumentException("개발 세션이 없습니다.");var project=service.ActiveProject();var prefs=service.Preferences(project);string preview=service.SessionPreview(project,preset,prefs);if(UxTheme.Confirm(this,"개발 세션 실행",preview+"\n\n요청 전달 후 각 프로그램의 초기화 완료는 별도입니다.","실행 요청","취소")!=0)return;requestBusy=true;status.Text="개발 세션 요청 중…";System.Threading.Tasks.Task.Factory.StartNew(()=>service.StartSession(project,preset,false,false,prefs)).ContinueWith(task=>Dispatcher.BeginInvoke((Action)delegate{requestBusy=false;if(task.IsFaulted){status.Text=task.Exception.GetBaseException().Message;return;}status.Text=task.Result.Result;if(config.CloseAfterLaunch)Dismiss();}));}finally{modal=false;}}
 }
 internal static class LaunchpadPreferences {
  public static void Show(Window owner,DesktopService service){var config=service.Launchpad();var dialog=UxTheme.Dialog(owner,"Launchpad 사용자화",560,640);var layout=new DockPanel{Margin=new Thickness(16)};var footer=new StackPanel();DockPanel.SetDock(footer,Dock.Bottom);layout.Children.Add(footer);var error=new TextBlock{Foreground=UxTheme.Accent,TextWrapping=TextWrapping.Wrap};footer.Children.Add(error);var actions=new WrapPanel{HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,12,0,0)};footer.Children.Add(actions);var fields=new StackPanel();layout.Children.Add(new ScrollViewer{Content=fields,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});dialog.Content=layout;
   Action<string,UIElement> field=(name,control)=>{fields.Children.Add(new TextBlock{Text=name,Foreground=UxTheme.Muted,Margin=new Thickness(0,8,0,4)});fields.Children.Add(control);AutomationProperties.SetName(control,name);};
   var shortcut=new TextBox{Text=config.Shortcut,IsReadOnly=true,ToolTip="클릭 후 Ctrl 또는 Alt를 포함한 키 조합을 누르세요."};shortcut.PreviewKeyDown+=delegate(object s,KeyEventArgs e){e.Handled=true;var key=e.Key==Key.System?e.SystemKey:e.Key;var mod=Keyboard.Modifiers;if(key==Key.LeftCtrl||key==Key.LeftAlt||key==Key.LeftShift||key==Key.RightCtrl||key==Key.RightAlt||key==Key.RightShift)return;string value=((mod&ModifierKeys.Control)!=0?"Ctrl+":"")+((mod&ModifierKeys.Alt)!=0?"Alt+":"")+((mod&ModifierKeys.Shift)!=0?"Shift+":"")+key;uint m,k;if(GuntLaunchpadHotkey.TryParse(value,out m,out k))shortcut.Text=value;else error.Text="Ctrl/Alt와 영문·숫자·기능 키 조합을 사용하세요.";};field("Launchpad 단축키 (키를 눌러 기록)",shortcut);var reset=new Button{Content="Ctrl+Alt+L로 초기화"};reset.Click+=delegate{shortcut.Text="Ctrl+Alt+L";};fields.Children.Add(reset);
   var enabled=new CheckBox{Content="전역 단축키 사용",IsChecked=config.HotkeyEnabled};fields.Children.Add(enabled);
   var monitor=new ComboBox{ItemsSource=new[]{"pointer","foreground"},SelectedItem=config.Monitor};field("표시 화면 (pointer: 마우스 / foreground: 현재 창)",monitor);
   var size=new ComboBox{ItemsSource=new[]{48,56,64,72,80},SelectedItem=config.IconSize};field("아이콘 크기 (DIP)",size);var columns=new ComboBox{ItemsSource=new[]{4,5,6,7,8},SelectedItem=config.Columns};field("최대 열 수",columns);
   var defaultCategory=new ComboBox{ItemsSource=config.Categories,SelectedItem=config.Categories.First(x=>x.Id==config.DefaultCategory)};field("기본 카테고리",defaultCategory);
   var theme=new ComboBox{ItemsSource=new[]{"original","mascot"},SelectedItem=config.IconTheme};field("아이콘 테마 (original / mascot)",theme);
   var animation=new CheckBox{Content="짧은 전환 사용 (Windows 애니메이션 설정 존중)",IsChecked=config.Animations};fields.Children.Add(animation);var close=new CheckBox{Content="실행 요청 전달 후 닫기",IsChecked=config.CloseAfterLaunch};fields.Children.Add(close);var transparency=new CheckBox{Content="투명 창 사용 (Launchpad 프로세스 재시작 후 반영)",IsChecked=config.Transparency};fields.Children.Add(transparency);
   var barStatus=service.State("launchpad-hotkey");fields.Children.Add(new TextBlock{Text="상단 바: "+DesktopService.S(barStatus,"Status","등록 결과 없음 · 상단 바 실행 필요"),Foreground=UxTheme.Muted,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,12,0,0)});
   string initial=service.Json.Serialize(config);bool saved=false;var save=new Button{Content="저장",BorderBrush=UxTheme.Accent};var cancel=new Button{Content="취소",IsCancel=true};actions.Children.Add(save);actions.Children.Add(cancel);
   Action gather=()=>{config.Shortcut=shortcut.Text;config.HotkeyEnabled=enabled.IsChecked==true;config.Monitor=Convert.ToString(monitor.SelectedItem);config.IconSize=Convert.ToInt32(size.SelectedItem);config.Columns=Convert.ToInt32(columns.SelectedItem);config.DefaultCategory=((LaunchpadCategory)defaultCategory.SelectedItem).Id;config.IconTheme=Convert.ToString(theme.SelectedItem);config.Animations=animation.IsChecked==true;config.CloseAfterLaunch=close.IsChecked==true;config.Transparency=transparency.IsChecked==true;};
   save.Click+=delegate{try{string previous=config.Shortcut;gather();var state=service.State("launchpad-hotkey");bool owned=DesktopService.S(state,"Shortcut")==config.Shortcut&&DesktopService.B(state,"Available");if(config.HotkeyEnabled&&!owned&&!GuntLaunchpadHotkey.Probe(config.Shortcut))throw new ArgumentException("다른 프로그램이 사용 중인 단축키입니다. 다른 조합을 선택하세요.");service.SaveLaunchpad(config);saved=true;dialog.Close();}catch(Exception e){error.Text=e.Message;}};
   dialog.Closing+=delegate(object sender,System.ComponentModel.CancelEventArgs e){gather();if(!saved&&service.Json.Serialize(config)!=initial&&UxTheme.Confirm(dialog,"미저장 변경","설정 변경을 버릴까요?","버리기","계속 편집")!=0)e.Cancel=true;};dialog.ShowDialog();
  }
 }
}
